"""Offline Android fakes shared by reminder regression and widget geometry tests.

Extracted from the earlier reminder/cache oracle; no dependency on its analysis tree.
These fakes intentionally replace services, not the production code being checked.
"""
import os
from pathlib import Path


def toolchain(parser, args):
    """Resolve configured JDK/SDK; never depend on an external analysis directory."""
    java_home = args.java_home
    android_home = args.android_home
    json_jar = args.json_jar
    if java_home is None:
        parser.error('set JAVA_HOME or pass --java-home')
    if android_home is None:
        parser.error('set ANDROID_HOME / ANDROID_SDK_ROOT or pass --android-home')
    if json_jar is None:
        parser.error('pass --json-jar pointing to an org.json jar (not android.jar)')
    suffix = '.exe' if os.name == 'nt' else ''
    javac = java_home / 'bin' / ('javac' + suffix)
    java = java_home / 'bin' / ('java' + suffix)
    android = android_home / 'platforms' / ('android-' + args.sdk_version) / 'android.jar'
    for name, path in [('javac', javac), ('java', java), ('Android platform jar', android), ('JSON jar', json_jar)]:
        if not path.is_file():
            parser.error(name + ' does not exist: ' + str(path))
    # Real org.json must precede android.jar's deliberately throwing SDK stubs.
    return javac, java, os.pathsep.join(map(str, [json_jar, android]))


def add_toolchain_args(parser):
    parser.add_argument('--java-home', type=Path, default=os.environ.get('JAVA_HOME'))
    parser.add_argument('--android-home', type=Path,
                        default=os.environ.get('ANDROID_HOME') or os.environ.get('ANDROID_SDK_ROOT'))
    parser.add_argument('--sdk-version', default='36')
    parser.add_argument('--json-jar', type=Path, default=os.environ.get('WEATHER_TEST_JSON_JAR'))

